 public AutopilotDtos.RecoveryAssessment recovery(String email,AutopilotDtos.RecoveryInput input){var user=users.findByEmail(email).orElseThrow();LocalDate today=todayDate();double consumed=diary.findByUserIdAndEntryDateOrderByLoggedAtAsc(user.getId(),today).stream().mapToDouble(FoodDiaryEntry::getCalories).sum();var mission=missions.findByUserId(user.getId());Double tdee=mission.map(m->(double)m.getMaintenanceCalories()).orElse(null);Double actual=tdee==null?null:tdee-consumed;double gap=balances.findTopByUserIdOrderByEntryDateDesc(user.getId()).map(DailyCalorieBalance::getPendingGapKcal).orElse(0.0);String status;List<String> flags=new ArrayList<>();if(Boolean.TRUE.equals(input.pain()))flags.add("pain reported");if(Boolean.TRUE.equals(input.lowIntake())||(tdee!=null&&consumed>0&&consumed<tdee*.65))flags.add("low intake");if(input.sleepHours()!=null&&input.sleepHours()<6)flags.add("short sleep reported");if(input.energyScore()!=null&&input.energyScore()<=2)flags.add("low energy reported");if(input.sorenessScore()!=null&&input.sorenessScore()>=8)flags.add("high soreness reported");if(!flags.isEmpty())status="Poor";else if(input.sleepHours()!=null&&input.sleepHours()>=8&&input.energyScore()!=null&&input.energyScore()>=4&&input.sorenessScore()!=null&&input.sorenessScore()<=3)status="Excellent";else if(input.energyScore()!=null&&input.energyScore()>=3&&(input.sorenessScore()==null||input.sorenessScore()<=5))status="Good";else status="Moderate";int activity=status.equals("Excellent")?100:status.equals("Good")?50:0;LocalDate original=mission.map(FatLossMission::getOriginalDeadline).orElse(null),current=mission.map(FatLossMission::getRevisedDeadline).orElse(null);double dailyPlan=mission.map(m->(double)Math.max(0,m.getMaintenanceCalories()-m.getDailyCalorieBudget())).orElse(0.0);long extraDays=gap>0&&dailyPlan>0?(long)Math.ceil(gap/dailyPlan):0;LocalDate proposed=current==null?null:current.plusDays(extraDays);String what=extraDays>0?"Extend the mission deadline by "+extraDays+" days; optional easy activity: "+activity+" kcal.":"Keep the current timeline; optional easy activity: "+activity+" kcal.";String why=flags.isEmpty()?"No low-readiness flags were reported; activity remains optional.":"Recovery flag(s): "+String.join(", ",flags)+". Prioritize rest and adequate meals; no backlog punishment.";if(actual!=null&&actual<0)why+=" Intake exceeded estimated TDEE; return to normal meals, with no meal skipping or punishment cardio.";String data="Consumed "+Math.round(consumed)+" kcal; estimated TDEE "+(tdee==null?"not logged":"mission maintenance "+Math.round(tdee))+"; actual deficit "+(actual==null?"unavailable":Math.round(actual)+" kcal (TDEE minus consumed, exercise not added)")+"; pending gap "+Math.round(gap)+" kcal; readiness "+status+".";String impact=extraDays>0?"Moves revised deadline from "+current+" to "+proposed+"; does not turn backlog into compulsory exercise.":"No deadline change; activity is optional and not added to the deficit calculation.";var m=new LinkedHashMap<String,Object>();m.put("what",what);m.put("why",why);m.put("dataInfluenced",data);m.put("impactIfAccepted",impact);m.put("proposedDeadline",proposed==null?null:proposed.toString());m.put("optionalActivityKcal",activity);m.put("userId",user.getId());var proposal=proposals.save(new CoachProposal(email,"RECOVERY_BACKLOG",toJson(m)));return new AutopilotDtos.RecoveryAssessment(status,why,consumed,tdee,actual,gap,activity,original,current,proposed,what,why,data,impact,proposal.getId());}
 public AutopilotDtos.BacklogState backlog(String email){var user=users.findByEmail(email).orElseThrow();var mission=missions.findByUserId(user.getId());var balance=balances.findTopByUserIdOrderByEntryDateDesc(user.getId());double gap=balance.map(DailyCalorieBalance::getPendingGapKcal).orElse(0.0);Double planned=mission.map(m->(double)Math.max(0,m.getMaintenanceCalories()-m.getDailyCalorieBudget())).orElse(null);var m=mission.orElse(null);return new AutopilotDtos.BacklogState(gap,planned,balance.map(DailyCalorieBalance::getActualDeficit).orElse(null),m==null?null:m.getOriginalDeadline(),m==null?null:m.getRevisedDeadline(),m==null?0:Math.max(0,ChronoUnit.DAYS.between(todayDate(),m.getRevisedDeadline())),false);}
