 @Transactional public AutopilotDtos.Proposal decide(String email,Long id,AutopilotDtos.Decision d){var p=proposals.findByIdAndUserEmail(id,email).orElseThrow(()->new NoSuchElementException("Proposal not found"));String a=d.action().toUpperCase(Locale.ROOT);if(!Set.of("ACCEPT","REJECT","EDIT").contains(a))throw new IllegalArgumentException("action must be ACCEPT, REJECT, or EDIT");Map<String,Object> m;try{m=json.readValue(p.getProposalJson(),new TypeReference<>(){});}catch(Exception e){m=new LinkedHashMap<>();}if(d.edits()!=null)m.putAll(d.edits());if(a.equals("ACCEPT")&&p.getType().equals("RECOVERY_BACKLOG")&&m.get("proposedDeadline") instanceof String date){var user=users.findByEmail(email).orElseThrow();missions.findByUserId(user.getId()).ifPresent(mission->mission.reviseDeadline(LocalDate.parse(date)));}if(a.equals("ACCEPT")&&p.getType().equals("MISSED_WORKOUT")){LocalDate target=LocalDate.parse(Objects.toString(m.get("suggestedDate")));boolean existing=days.findByUserEmailAndPlanDate(email,target).isPresent()||workoutService.sessions(email).stream().anyMatch(w->w.sessionDate()!=null&&w.sessionDate().toLocalDate().equals(target));var slot=plans.findByUserEmailAndDayOfWeek(email,target.getDayOfWeek()).orElse(null);boolean scheduled=slot!=null&&slot.getFocus()!=null&&!slot.getFocus().toLowerCase(Locale.ROOT).matches(".*\\b(rest|off|recovery)\\b.*");if(existing||scheduled)throw new IllegalStateException("Suggested date is no longer open; request a new reschedule.");var base=buildToday(email);String workoutName=Objects.toString(m.get("workoutName"),"Rescheduled workout");var nextPlan=new AutopilotDtos.DailyPlan(target,new AutopilotDtos.Workout(workoutName,List.of(workoutName),base.workout().exercises(),base.workout().durationMinutes()),base.cardio(),base.nutrition(),base.recoveryStatus(),"Rescheduled workout; preserve recovery and do not stack sessions.",base.dailyGoals(),"Follow the next saved split in sequence.",base.expressMode());save(email,nextPlan);}p.decide(a,toJson(m));return dto(p);}
 private AutopilotDtos.Proposal dto(CoachProposal p){try{var m=json.readValue(p.getProposalJson(),new TypeReference<Map<String,Object>>(){});return new AutopilotDtos.Proposal(p.getId(),p.getType(),p.getStatus(),Objects.toString(m.get("what"),""),Objects.toString(m.get("why"),""),Objects.toString(m.get("dataInfluenced"),""),Objects.toString(m.get("impactIfAccepted"),""),m,p.getCreatedAt());}catch(Exception e){throw new IllegalStateException(e);}}
 private AutopilotDtos.DailyPlan read(String jsonText){try{return json.readValue(jsonText,AutopilotDtos.DailyPlan.class);}catch(Exception e){throw new IllegalStateException(e);}}
 private String toJson(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
